package com.lld.splitwise.dto;

import java.math.BigDecimal;
import java.util.List;

/**
 * idempotencyKey: generated by the CLIENT once per "Add expense" action (e.g. a UUID)
 * and re-sent unchanged on every retry of that same action.
 */
public record CreateExpenseRequest(String idempotencyKey,
                                   String requesterId,
                                   String groupId,
                                   String description,
                                   String paidByUserId,
                                   BigDecimal amount,
                                   String splitType,
                                   List<SplitRequest> splits) {
}
